package glitch

import data.glitch_lib

# Helper function to extract string values from different node types
get_string_value(node) = value {
    node.ir_type == "String"
    value := node.value
} else {
    node.ir_type == "VariableReference"
    value := node.value
} else {
    node.ir_type == "Integer"
    value := sprintf("%d", [node.value])
} else {
    # For KeyValue nodes in Chef hashes, get the value field
    node.ir_type == "KeyValue"
    value := get_string_value(node.value)
}

# Check if a node represents a bind address configuration
is_bind_address_node(node) {
    # Check if the node has a key that suggests bind address
    node.ir_type == "KeyValue"
    key_name := get_string_value(node.key)
    lower_key := lower(key_name)
    regex.match(".*(bind|ip|address|listen|interface|net_bind|server_bind).*", lower_key)
} else {
    # Check if the node is a variable with bind address name
    node.ir_type == "Variable"
    lower_name := lower(node.name)
    regex.match(".*(bind|ip|address|listen|interface|net_bind|server_bind).*", lower_name)
}

# Check if a value represents an open bind address
is_open_bind_address(value) {
    value == "0.0.0.0"
} else {
    value == "::/0"
} else {
    value == "0.0.0.0/0"
} else {
    value == "0.0.0.0/0"
}

# Helper to walk through nested structures and find bind address violations
find_bind_address_violations(node, path, violations) {
    walk(node, [path, current_node])
    is_bind_address_node(current_node)
    value_str := get_string_value(current_node)
    is_open_bind_address(value_str)
    violations := [current_node]
} else {
    violations := []
}

