package glitch

import data.glitch_lib

# Helper function to get the string representation of a key
get_key_string(key) = str {
    key.ir_type == "String"
    str := key.value
} else {
    key.ir_type == "VariableReference"
    str := key.value
} else {
    key.ir_type == "Access"
    str := key.right.value
} else {
    str := key.code
}

# Check if a value represents an open bind address (0.0.0.0 or ::/0)
is_open_bind_address(value) {
    value.ir_type == "String"
    value.value == "0.0.0.0"
} else {
    value.ir_type == "String"
    value.value == "::/0"
}

# Recursive function to find open bind addresses in hash structures
find_open_bind_address_in_hash(node, path) = result {
    node.ir_type == "Hash"
    entry := node.value[_]
    value_node := entry.value

    # Check if this entry is the open bind address
    is_open_bind_address(value_node)
    key_string := get_key_string(entry.key)
    lower_key := lower(key_string)
    regex.match(".*(bind|ip|address|interface|net_bind|server_bind|addr|listen|port|bind_address|bind_addr|bind-address).*", lower_key)

    result := {
        "element": value_node,
        "key": key_string,
        "value": value_node.value
    }
} else {
    node.ir_type == "Hash"
    entry := node.value[_]
    nested_result := find_open_bind_address_in_hash(entry.value, path)
    result := nested_result
}

# Main rule to detect open bind addresses in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Get all variables in the parent
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # For variables with Hash values, recursively search for open bind addresses
    var.value.ir_type == "Hash"
    search_result := find_open_bind_address_in_hash(var.value, [])

    result := {
        "type": "sec_invalid_bind",
        "element": search_result.element,
        "path": parent.path,
        "description": sprintf("Insecure bind address: key '%s' set to '%s' in variable '%s'", [search_result.key, search_result.value, var.name])
    }
}

